package bookstore

import "sort"

// Cost returns the total cost, in cents, of the given basket of books,
// applying the largest possible discount.
//
// Books are identified by the integers 1-5. A single copy costs 800
// cents, and buying a group of k distinct titles (k = 2..5) earns a
// discount of 5%, 10%, 20%, 25% respectively.
func Cost(books []int) int {
	var counts [5]int
	for _, b := range books {
		if b >= 1 && b <= 5 {
			counts[b-1]++
		}
	}
	sort.Slice(counts[:], func(i, j int) bool { return counts[i] > counts[j] })
	return minCost(counts, make(map[[5]int]int))
}

// groupCost[k] is the total cost, in cents, of a group of k distinct
// titles: 800 per book, minus the discount for that group size.
var groupCost = [6]int{0, 800, 1520, 2160, 2560, 3000}

// minCost computes the minimum cost of the books described by counts,
// which must be sorted in non-increasing order. It tries every possible
// first group (any subset of the titles that still have copies) and
// memoizes the result.
func minCost(counts [5]int, memo map[[5]int]int) int {
	if counts[0] == 0 {
		return 0
	}
	if cost, ok := memo[counts]; ok {
		return cost
	}

	k := 0
	for k < 5 && counts[k] > 0 {
		k++
	}

	best := groupCost[k] // hmm, no — the upper bound should be something safe
	...
}
```

Wait, about the initial value of best: the maximum cost of any partition is 800 * total number of books (no discounts). Let's use that as the initial best: total * 800. Actually, more simply: initialize best to a very large value, or compute 800*total. Let's use the 800*total upper bound.

