```go
// sortDesc sorts the five counts in non-increasing order.
func sortDesc(c *[5]int) {
	for i := 0; i < 4; i++ {
		for j := i + 1; j < 5; j++ {
			if c[j] > c[i] {
				c[i], c[j] = c[j], c[i]
			}
		}
	}
}
```

